sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float extent;
uniform float strength;
uniform float rounding;
uniform float feather;
uniform float tint;
layout(color) uniform half4 color;
uniform float punch;

half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0001) return half4(0);
    float2 n = abs((coord / max(size, float2(1.0)) - 0.5) * 2.0);
    float p = max(rounding, 0.5);
    float d = pow(pow(n.x, p) + pow(n.y, p), 1.0 / p);
    float s = max(extent, 0.001);
    float v = smoothstep(s * (1.0 - feather * 0.25), s * (1.0 + feather * 3.0) + 0.001, d) * clamp(strength, 0.0, 1.0);
    if (punch > 0.5) return c * half(1.0 - v);
    float3 rgb = float3(c.rgb / c.a);
    rgb = mix(max(rgb - v * (1.0 - tint), 0.0), float3(color.rgb), tint * v);
    return half4(half3(rgb) * c.a, c.a);
}
